/* controls */
.controls { display: grid; grid-template-columns: 1.15fr 1fr 1fr 1.2fr; gap: 10px; align-items: stretch; }
.ctrl-group { border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,.022); padding: 9px 11px; min-width: 0; }
.ctrl-label { display: flex; justify-content: space-between; align-items: center; font-size: 7.5px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--dim); margin-bottom: 6px; }
.ctrl-label b { color: var(--orange-2); font-family: var(--mono); font-size: 10px; }
.steer-pad { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.hold-btn {
  min-height: 52px; border-radius: 9px; border: 1px solid rgba(255,255,255,.17);
  background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.025));
  font-size: 10px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  touch-action: none; user-select: none; -webkit-user-select: none; transition: .08s;
}
.hold-btn small { font-size: 7.5px; color: var(--dim); letter-spacing: .08em; font-weight: 500; text-transform: none; }
.hold-btn:hover { border-color: rgba(255,255,255,.35); }
.hold-btn.on, .hold-btn:active { background: linear-gradient(180deg, #ff9a3d, #f06a00); border-color: #ffb15c; color: #170e06; transform: translateY(1px); }
.hold-btn.on small, .hold-btn:active small { color: rgba(23,14,6,.65); }
.hold-btn.big { min-height: 66px; font-size: 13px; letter-spacing: .1em; }
.toggle-btn {
  min-height: 38px; width: 100%; border-radius: 8px; border: 1px solid rgba(255,255,255,.16);
  font-size: 10px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase;
  background: rgba(255,255,255,.04);
}
.toggle-btn.on { background: rgba(255,122,26,.16); border-color: rgba(255,177,92,.6); color: var(--orange-2); box-shadow: inset 0 0 18px rgba(255,122,26,.1); }
.toggle-btn.green.on { background: rgba(125,211,167,.12); border-color: rgba(125,211,167,.5); color: var(--green); }
.hint { font-size: 8.5px; line-height: 1.35; color: var(--dim); margin-top: 5px; }
.auto-row { display: flex; align-items: center; gap: 7px; margin-top: 5px; font-size: 8.5px; color: var(--muted); }
.auto-row input { accent-color: var(--orange); width: 14px; height: 14px; }
.mini-gauge { display: flex; align-items: baseline; gap: 4px; font-size: 8px; color: var(--dim); }
.mini-gauge b { font-family: var(--mono); font-size: 22px; color: var(--text); line-height: 1; }
.pressure-bar { height: 6px; border-radius: 4px; background: linear-gradient(90deg, #2e9b6d, #7dd3a7 35%, #ffc94a 60%, #ff6b6b); position: relative; margin-top: 6px; }
.pressure-bar .needle { position: absolute; top: -3px; width: 2px; height: 12px; background: #fff; box-shadow: 0 0 6px #fff; transition: left .1s linear; }
.pressure-bar .band { position: absolute; top: -2px; bottom: -2px; border-left: 1px dashed rgba(255,255,255,.7); border-right: 1px dashed rgba(255,255,255,.7); }

/* process stages */
.process-grid { display: grid; grid-template-columns: 1.1fr 1fr 1.2fr; gap: 10px; align-items: stretch; }
.process-card { border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,.022); padding: 10px 12px; }
.process-card .ctrl-label { margin-bottom: 5px; }
.big-read { font-family: var(--mono); font-size: 27px; line-height: 1; letter-spacing: -.04em; }
.big-read small { font-family: var(--font); font-size: 9px; color: var(--dim); letter-spacing: .08em; }
.process-meter { height: 8px; border-radius: 5px; background: rgba(255,255,255,.08); position: relative; overflow: hidden; margin: 8px 0 4px; }
.process-meter i { display: block; height: 100%; background: var(--orange); border-radius: 5px; transition: width .12s linear; }
.process-meter .danger-zone { position: absolute; top: 0; bottom: 0; right: 0; width: 14%; background: repeating-linear-gradient(135deg, rgba(255,107,107,.35) 0 4px, transparent 4px 8px); }
.process-meter .safe-zone { position: absolute; top: 0; bottom: 0; background: rgba(125,211,167,.14); border-left: 1px dashed rgba(125,211,167,.5); border-right: 1px dashed rgba(125,211,167,.5); }
.flow-slider { width: 100%; accent-color: var(--orange); height: 26px; cursor: pointer; }
.split { display: flex; gap: 8px; align-items: stretch; }
.split > * { flex: 1; }
.quality-line { display: flex; justify-content: space-between; font-size: 9px; color: var(--dim); margin-top: 4px; }
.quality-line b { font-family: var(--mono); color: var(--text); }
.finish-row { display: flex; align-items: center; gap: 10px; margin-top: 8px; }
.finish-row .btn { flex: 1; }

/* toasts */
.toast-layer { position: absolute; top: 64px; left: 50%; transform: translateX(-50%); z-index: 20; display: flex; flex-direction: column; gap: 7px; align-items: center; pointer-events: none; width: max-content; max-width: 90%; }
.toast {
  padding: 8px 14px; border-radius: 8px; font-size: 11px; font-weight: 600; letter-spacing: .02em;
  background: rgba(9,20,28,.94); border: 1px solid var(--line-strong); box-shadow: 0 14px 34px rgba(0,0,0,.45);
  animation: toastIn .22s ease, toastOut .3s ease 2.9s forwards; display: flex; gap: 8px; align-items: center;
}
.toast.good { border-color: rgba(125,211,167,.5); color: #c4efdb; }
.toast.warn { border-color: rgba(255,201,74,.5); color: #ffe4a8; }
.toast.bad { border-color: rgba(255,107,107,.55); color: #ffc0c0; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-6px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* overlays + results */
.overlay { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 18px;
  background: rgba(4,9,13,.8); backdrop-filter: blur(9px); overflow-y: auto; }
.overlay.hidden { display: none; }
.modal-card {
  width: min(720px, 100%); max-height: calc(100dvh - 60px); overflow-y: auto;
  background: linear-gradient(180deg, #10202b, #0a151d); border: 1px solid var(--line-strong);
  border-radius: 18px; padding: clamp(20px, 3vw, 34px); box-shadow: 0 30px 90px rgba(0,0,0,.65);
  animation: modalIn .22s ease;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(10px) scale(.99); } }
.modal-kicker { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 10px; }
.modal-card h2 { font-size: clamp(26px, 3vw, 38px); line-height: 1; letter-spacing: -.03em; text-transform: uppercase; margin-bottom: 8px; }
.modal-card .sub { color: var(--muted); font-size: 12.5px; line-height: 1.55; }
.status-chip { display: inline-flex; align-items: center; gap: 7px; padding: 6px 10px; border-radius: 7px; font-size: 9px; letter-spacing: .12em; text-transform: uppercase; font-weight: 750; }
.status-chip.ok { background: rgba(125,211,167,.12); border: 1px solid rgba(125,211,167,.4); color: var(--green); }
.status-chip.fail { background: rgba(255,107,107,.12); border: 1px solid rgba(255,107,107,.4); color: var(--red); }
.stars { display: flex; gap: 5px; font-size: 24px; letter-spacing: 2px; color: rgba(255,255,255,.13); margin: 14px 0; }
.stars i { font-style: normal; }
.stars i.on { color: var(--orange-2); text-shadow: 0 0 20px rgba(255,177,92,.5); }
.quality-list { display: grid; gap: 7px; margin: 16px 0; }
.q-row { display: grid; grid-template-columns: 108px 1fr 34px; gap: 10px; align-items: center; font-size: 9.5px; color: var(--muted); letter-spacing: .04em; }
.q-row b { font-family: var(--mono); font-size: 10px; color: var(--text); text-align: right; }
.q-track { height: 5px; border-radius: 4px; background: rgba(255,255,255,.08); overflow: hidden; }
.q-track i { display: block; height: 100%; background: linear-gradient(90deg, var(--orange), var(--orange-2)); border-radius: 4px; }
.fin-table { border-top: 1px solid var(--line); margin-top: 16px; }
.fin-row { display: flex; justify-content: space-between; gap: 14px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.05); font-size: 11.5px; color: var(--muted); }
.fin-row b { font-family: var(--mono); color: var(--text); font-weight: 600; }
.fin-row.total { font-size: 15px; color: var(--text); font-weight: 750; padding-top: 12px; border-bottom: 0; }
.fin-row.total b { color: var(--orange-2); font-size: 21px; letter-spacing: -.02em; }
.fin-row.neg b { color: #ff9b9b; }
.xp-block { margin-top: 18px; }
.xp-block .aside-title { padding: 0 0 8px; }
.xp-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
.xp-item { border: 1px solid var(--line); border-radius: 8px; padding: 8px; font-size: 8px; color: var(--dim); text-transform: uppercase; letter-spacing: .06em; }
.xp-item b { display: block; color: var(--text); font-size: 9.5px; margin-bottom: 3px; text-transform: none; letter-spacing: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.xp-item .xpbar { height: 3px; border-radius: 2px; background: rgba(255,255,255,.1); margin-top: 6px; overflow: hidden; }
.xp-item .xpbar i { display: block; height: 100%; background: var(--orange); }
.modal-actions { display: flex; gap: 10px; margin-top: 22px; flex-wrap: wrap; }
.modal-actions .btn { flex: 1; min-width: 140px; }

/* sheet / help */
.sheet-overlay { z-index: 32; }
.sheet-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; margin-top: 16px; }
.sheet-option { text-align: left; border: 1px solid var(--line); border-radius: 10px; padding: 12px; background: rgba(255,255,255,.022); transition: .15s; position: relative; }
.sheet-option:hover { border-color: rgba(255,177,92,.45); background: rgba(255,122,26,.055); }
.sheet-option.selected { border-color: var(--orange); background: rgba(255,122,26,.1); }
.sheet-option h4 { font-size: 11.5px; margin-bottom: 4px; }
.sheet-option .price { font-family: var(--mono); font-size: 10px; color: var(--orange-2); margin-bottom: 6px; }
.sheet-option p { font-size: 9.5px; line-height: 1.45; color: var(--muted); }
.sheet-option .best { position: absolute; top: 8px; right: 8px; font-size: 7px; letter-spacing: .1em; color: var(--green); text-transform: uppercase; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 16px; }
.help-block h4 { font-size: 10px; letter-spacing: .13em; text-transform: uppercase; color: var(--orange-2); margin-bottom: 7px; }
.help-block p, .help-block li { font-size: 11.5px; line-height: 1.6; color: var(--muted); }
.help-block ul { padding-left: 14px; list-style: disc; }
.key { display: inline-block; padding: 1px 5px; border: 1px solid var(--line-strong); border-radius: 4px; font-family: var(--mono); font-size: 9px; color: var(--text); }

