  ctx.restore();
}

drawSpoil(ctx, x, gy, s) {
  ctx.save();
  const g = ctx.createLinearGradient(0, gy - 22 * s, 0, gy);
  g.addColorStop(0, '#6b553d'); g.addColorStop(1, '#463726');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(x - 20 * s, gy);
  ctx.quadraticCurveTo(x - 12 * s, gy - 18 * s, x, gy - 21 * s);
