  ctx.fillRect(x - 2.5 * s, gy - 6 * s, 5 * s, 1.8 * s);
  ctx.fillStyle = '#33251a';
  ctx.fillRect(x - 5 * s, gy - 1 * s, 10 * s, 1.5 * s);
  ctx.restore();
}

drawExcavator(ctx, x, gy, s) {
  ctx.save();
  ctx.fillStyle = '#2b3033';
