      ctx.strokeStyle = 'rgba(190,150,100,.3)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(sx - half * 1.1, v.groundY); ctx.lineTo(sx - half, v.groundY + depth);
      ctx.moveTo(sx + half * 1.1, v.groundY); ctx.lineTo(sx + half, v.groundY + depth);
      ctx.stroke();
      // label
      ctx.fillStyle = 'rgba(7,16,23,.8)';
      ctx.strokeStyle = isExit ? 'rgba(94,214,255,.5)' : 'rgba(255,177,92,.45)';
      ctx.lineWidth = 1;
      const tw = 42, th = 15;
      this.rr(ctx, sx - tw / 2, v.groundY + depth + 5, tw, th, 4);
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = isExit ? '#9fe6ff' : '#ffc27a';
      ctx.font = 'bold 7px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText(label, sx, v.groundY + depth + 15);
